def run(state, tools, student):
    before = state.notes.get("before_failed")
    res = tools.run_tests()
    state.test_output = res.get("output", "")
    state.failures = res.get("failures", [])
    state.last_full_run = {"passed": res.get("passed"), "failed": res.get("failed")}
    after = res.get("failed", 0)
    state.notes["need_verify"] = False

    if after == 0:
        state.done = True
        state.summary = "all tests pass after patch"
        return state

    current = state.notes.get("current_test")
    improved = before is None or after < before

    if not improved and state.patches:
        last = state.patches[-1]
        if last.get("ok"):
            rb = tools.edit_file(last["file"], last["replace"], last["search"])
            if isinstance(rb, dict) and rb.get("ok"):
                last["ok"] = False
                last["rolled_back"] = True

    if current and not improved:
        tried = state.notes.setdefault("tried_tests", [])
        if current not in tried:
            tried.append(current)

    state.summary = f"verify: {after} failed (before {before}, improved={improved})"
    return state
