from pydantic import BaseModel

NAME = "locate-and-patch"
MAX_ATTEMPTS = 3


class Patch(BaseModel):
    search: str
    replace: str


def applies(state) -> bool:
    if state.notes.get("pending_verify"):
        return False
    if not state.failures:
        return False
    return state.notes.get("patch_attempts", 0) < MAX_ATTEMPTS


def _pick_suspect(state, tools):
    tried = set(state.notes.get("tried", []))
    for failure in state.failures:
        for frame in reversed(failure.get("frames", [])):
            path = (frame.get("file") or "").replace("\\", "/")
            if state.task_dir and path.startswith(state.task_dir):
                path = path[len(state.task_dir):].lstrip("/")
            name = path.split("/")[-1]
            if not path or "/tests/" in path or path.startswith("tests/"):
                continue
            if name.startswith("test_") or name == "conftest.py":
                continue
            key = f"{path}:{frame.get('line')}"
            if key in tried:
                continue
            try:
                tools.read_file(path, 1, 1)
            except Exception:
                continue
            return {"file": path, "line": frame.get("line"), "function": frame.get("function", "")}
    return None


def _excerpt(tools, suspect):
    line = suspect.get("line") or 1
    try:
        return tools.read_file(suspect["file"], max(1, line - 12), line + 18)
    except Exception:
        try:
            return tools.read_file(suspect["file"])
        except Exception:
            return ""


def run(state, tools, student):
    suspect = _pick_suspect(state, tools)
    if suspect is None:
        state.notes["patch_attempts"] = MAX_ATTEMPTS
        state.summary = "no editable source frame in the tracebacks"
        return state
    state.suspect = suspect
    excerpt = _excerpt(tools, suspect)
    state.context_snippet = excerpt
    failure = state.failures[0]
    err = (failure.get("error") or "").splitlines()[0][:200]
    prompt = (
        f"A pytest suite is failing. Failing test: {failure.get('test')}\n"
        f"Error: {err}\n\n"
        f"Most likely buggy location: {suspect['file']}:{suspect['line']} in {suspect['function']}\n\n"
        f"Code:\n{excerpt}\n\n"
        "Give the exact minimal edit that fixes the bug: the exact text to search for "
        "(verbatim, as it appears in the file) and the replacement text. Do not change tests."
    )
    try:
        answer = student.ask("patch", prompt, Patch)
    except Exception:
        answer = {}
    search = (answer or {}).get("search", "") or ""
    replace = (answer or {}).get("replace", "") or ""
    state.notes["patch_attempts"] = state.notes.get("patch_attempts", 0) + 1
    key = f"{suspect['file']}:{suspect['line']}"
    if not search.strip():
        state.notes.setdefault("tried", []).append(key)
        state.summary = "student produced no usable search text"
        return state
    res = tools.edit_file(suspect["file"], search, replace)
    ok = bool(res.get("ok")) if isinstance(res, dict) else bool(res)
    state.patches.append({"file": suspect["file"], "search": search, "replace": replace, "ok": ok})
    if ok:
        state.notes["prev_failed"] = (state.last_full_run or {}).get("failed", 0)
        state.notes["pending_verify"] = True
        state.summary = f"applied one patch to {suspect['file']}"
    else:
        state.notes.setdefault("tried", []).append(key)
        state.summary = f"edit did not apply at {suspect['file']} (search text not found)"
    return state
